CREATE TABLE IF NOT EXISTS expedientes (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, title VARCHAR(255) NOT NULL, description TEXT, topic VARCHAR(100), status VARCHAR(50) DEFAULT 'RECEIVED', owner_user_id UUID REFERENCES users(id), created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
